# backend/app/routers/flow_extension_bundle.py
from __future__ import annotations

import base64
import io
import zipfile
from pathlib import Path

# Self-contained bundle fallback for Docker production containers
EMBEDDED_EXTENSION_ZIP_B64 = ""

def get_extension_zip_bytes() -> bytes:
    candidate_paths = [
        Path(__file__).resolve().parents[3] / "extension" / "scriptoria-flow-bridge",
        Path("/app/extension/scriptoria-flow-bridge"),
        Path.cwd() / "extension" / "scriptoria-flow-bridge",
        Path.cwd().parent / "extension" / "scriptoria-flow-bridge",
    ]
    for p in candidate_paths:
        if p.exists() and p.is_dir():
            buf = io.BytesIO()
            with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
                for file_path in sorted(p.rglob("*")):
                    if file_path.is_file():
                        zf.write(file_path, file_path.relative_to(p))
            return buf.getvalue()

    return base64.b64decode(EMBEDDED_EXTENSION_ZIP_B64)
